            $('.fi-fc').addEventListener('change', e => { fCat = e.target.value; txView(); }); const q = $('.fi-fq'); q.addEventListener('input', () => { fQ = q.value.trim().toLowerCase(); const p = q.selectionStart; txView(); const n = $('.fi-fq'); n.focus(); n.setSelectionRange(p, p); });
