        const linkSel = (cat, val) => cat === SAVE ? `<label class="oa-f w fi-link">Sparziel<select class="oa-in" name="link"><option value="">–</option>${goals.map(g => `<option value="${esc(g.id)}"${val === g.id ? ' selected' : ''}>${esc(g.name)}</option>`).join('')}</select></label>` : cat === DEBT ? `<label class="oa-f w fi-link">Schuld<select class="oa-in" name="link"><option value="">–</option>${debts.map(d => `<option value="${esc(d.id)}"${val === d.id ? ' selected' : ''}>${esc(d.name)}</option>`).join('')}</select></label>` : '<span class="fi-link"></span>';
